import org.junit.Assert;

public class TestClass {
    // Minimal helper class to demonstrate Number return type
    static class BrowseHistory {
        private Integer currentBrowsePoint;
        public Integer getCurrentBrowsePoint() { return currentBrowsePoint; }
        public void addOrReplace(int value) { this.currentBrowsePoint = value; }
    }

    public void testMethod() {
        BrowseHistory history = new BrowseHistory();
        history.addOrReplace(10);
        // Matches: $expected=10 (int), $actual=history.getCurrentBrowsePoint() (Integer)
        Assert.assertTrue(10 == history.getCurrentBrowsePoint());

        int localValue = 20;
        history.addOrReplace(localValue);
        // Matches: $expected=localValue (int), $actual=history.getCurrentBrowsePoint() (Integer)
        Assert.assertTrue(localValue == history.getCurrentBrowsePoint());

        // Does not match: $actual is a primitive int, not an instance of Number
        Assert.assertTrue(10 == 10);
        // Does not match: $actual is an int (result of length()), not an instance of Number
        Assert.assertTrue("hello".length() == 5);
    }
}

