import org.junit.Assert;

public class NegativeTestClass {
    // Minimal helper class
    static class BrowseHistory {
        private Integer currentBrowsePoint;
        public Integer getCurrentBrowsePoint() { return currentBrowsePoint; }
        public void addOrReplace(int value) { this.currentBrowsePoint = value; }
    }

    public void testMethod() {
        int primitiveValue = 10;
        // $actual is a primitive int, not a java.lang.Number; rule guard prevents match.
        Assert.assertTrue(10 == primitiveValue);

        // Already uses assertEquals; rule pattern does not match.
        Assert.assertEquals(10, primitiveValue);

        String stringValue = "10";
        // $actual is a String, not a java.lang.Number; rule guard prevents match.
        Assert.assertTrue(10 == Integer.parseInt(stringValue));

        // $actual could be null; rule preserves behavior (NPE on .intValue() vs false on ==)
        BrowseHistory history = new BrowseHistory();
        history.addOrReplace(0); // Ensure non-null for other test cases
        history.currentBrowsePoint = null; // Set to null for this specific test
        Assert.assertTrue(10 == history.getCurrentBrowsePoint()); // Behavior change for null is acceptable for this cleanup
    }
}
